import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Combat Actions y Special Attacks","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/actions.md","filePath":"es/game-design/combat/actions.md"}'),r={name:"es/game-design/combat/actions.md"};function n(d,e,s,c,l,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="combat-actions-and-special-attacks" tabindex="-1">Combat Actions y Special Attacks <a class="header-anchor" href="#combat-actions-and-special-attacks" aria-label="Enlace permanente a &quot;Combat Actions y Special Attacks&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Los ejemplos numéricos son hipótesis de prototipo, no equilibrio definitivo. <strong>Implementación/disponibilidad:</strong> no establecida para estas mecánicas. <strong>Verificación:</strong> revisión documental, sin prototipo jugable. <strong>Revisión:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a> · <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Registro de variables de combate</a></p><h2 id="a-shared-action-vocabulary" tabindex="-1">Un vocabulario compartido de acciones <a class="header-anchor" href="#a-shared-action-vocabulary" aria-label="Enlace permanente a &quot;Un vocabulario compartido de acciones&quot;">​</a></h2><p>Usar <strong>Special Attack (SA)</strong> como abreviatura de técnicas especiales de combate aprendidas; Combat Action es el esquema más amplio que incluye ataques básicos y respuestas defensivas. Skill aporta capacidad, Technique conocimiento, Familiarity fluidez, Prepared Repertoire opciones listas y la ejecución del jugador las aplica.</p><table tabindex="0"><thead><tr><th>Categoría</th><th>Dirección inicial del volumen de contenido</th><th>Solo ejemplos</th></tr></thead><tbody><tr><td>SA específica del arma</td><td>Aproximadamente 4 por arma</td><td>War Hammer: Heavy Blow, Crushing Arc; otras entradas por definir</td></tr><tr><td>SA de familia</td><td>Aproximadamente 3 por familia de armas</td><td>Mace Fighting: concepto de Stun breve; otras entradas por definir</td></tr><tr><td>Acción universal</td><td>Pequeño conjunto marcial compartido</td><td>Brace, Parry y otras respuestas defensivas elegibles</td></tr></tbody></table><p>Son volúmenes de contenido, no ranuras fijas, catálogo completo, elegibilidad universal garantizada ni definiciones finales de efectos. La duración de Stun y todos los valores de daño/trauma siguen sin resolverse.</p><h2 id="learning-familiarity-and-prepared-options" tabindex="-1">Aprendizaje, Familiarity y opciones preparadas <a class="header-anchor" href="#learning-familiarity-and-prepared-options" aria-label="Enlace permanente a &quot;Aprendizaje, Familiarity y opciones preparadas&quot;">​</a></h2><p>El nivel de habilidad por sí solo no otorga SA. Entrenadores, academias, escuelas marciales, facciones, libros/manuales, maestros, exploración, desafíos/competiciones y enseñanza de jugadores permitida más adelante pueden transmitirlas. <a href="/Syrolands-Public/es/game-design/characters/familiarity.html">Familiarity compartida</a> normaliza <strong>Learned → Practiced → Mastered</strong>, adquisición permanente y fluidez que puede decaer para combate y patrones de hechizos.</p><p>Un prototipo inicial de experiencia de Prepared Combat Repertoire usa <strong>5 ranuras de SA</strong>, no un límite aceptado. Un guerrero puede conocer más de las que prepara. No vincular cinco ranuras a INT: algo de capacidad extra, cambios más rápidos o apoyo para técnicas complejas son posibilidades posteriores, e INT no debe convertirse en una inversión obligatoria para guerreros. Las técnicas preparadas podrían perder fluidez más lentamente; las reglas siguen sin resolverse. No estar preparado o ser incompatible es distinto de olvidar conocimientos; los cambios de acceso/preparación durante el combate necesitan diseño.</p><h2 id="canonical-action-schema" tabindex="-1">Esquema canónico de acciones <a class="header-anchor" href="#canonical-action-schema" aria-label="Enlace permanente a &quot;Esquema canónico de acciones&quot;">​</a></h2><p>Cada acción debería completar los campos relevantes o marcarlos explícitamente como Sin resolver / no aplicable. Es un registro de diseño, no un esquema de base de datos o red.</p><table tabindex="0"><thead><tr><th>Campo</th><th>Qué debe especificar la acción</th></tr></thead><tbody><tr><td>Nombre</td><td>Identidad reconocible de la acción</td></tr><tr><td>Familia de acción</td><td>Clasificación básica, específica de arma, de familia o universal/defensiva</td></tr><tr><td>Elegibilidad de arma/familia</td><td>Equipo compatible y restricciones de familia</td></tr><tr><td>Técnica aprendida requerida</td><td>Requisito de conocimiento; ninguno solo cuando sea explícitamente apropiado</td></tr><tr><td>Alcance</td><td>Máximo físico para esta acción</td></tr><tr><td>Distancia mínima/efectiva</td><td>Límite de proximidad y bandas útiles/óptimas</td></tr><tr><td>Huella espacial</td><td>Región, arco, línea, área u otra forma justificada</td></tr><tr><td>Coste de stamina</td><td>Compromiso y etapas de cobro; sin valor asignado</td></tr><tr><td>Wind-up</td><td>Preparación antes de la ejecución activa</td></tr><tr><td>Ventana activa</td><td>Intervalo en que puede resolverse contacto/efecto autoritativo</td></tr><tr><td>Recuperación</td><td>Restricciones antes de acciones posteriores</td></tr><tr><td>Modificador de precisión</td><td>Contribución a probabilidad de impacto/ubicación, distinta del fallo automático de activación de SA</td></tr><tr><td>Modificador de manejo</td><td>Contribución a coste/recuperación/control</td></tr><tr><td>Modificador de consistencia</td><td>Contribución a repetibilidad/variación</td></tr><tr><td>Perfil de daño/trauma</td><td>Comportamiento y tipo de daño global frente a trauma local</td></tr><tr><td>Perfil de apuntado</td><td>Objetivos/regiones pretendidos; intención no es impacto garantizado</td></tr><tr><td>Movimiento permitido</td><td>Restricciones de movimiento durante las fases</td></tr><tr><td>Interrumpibilidad</td><td>Qué puede alterar cada fase; estado/coste resultante sin resolver</td></tr><tr><td>Señal anticipatoria</td><td>Animación/postura/sonido y señales informativas permitidas</td></tr><tr><td>Relaciones de respuesta</td><td>Respuestas compatibles, fintas, flanqueos y límites de enfrentamiento</td></tr><tr><td>Efectos de Familiarity</td><td>Cambios cualitativos de ejecución por nivel compartido</td></tr><tr><td>Comportamiento Legacy</td><td>Golpe encolado o defensa inmediata; reglas de invalidación</td></tr><tr><td>Comportamiento Modern</td><td>Inicio activado y restricciones propias de preparación/fases</td></tr></tbody></table><h3 id="example-records-deliberately-incomplete" tabindex="-1">Registros de ejemplo deliberadamente incompletos <a class="header-anchor" href="#example-records-deliberately-incomplete" aria-label="Enlace permanente a &quot;Registros de ejemplo deliberadamente incompletos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Acción</th><th>Alcance de diseño</th><th>Dirección de tiempos/recursos/espacio</th><th>Respuestas / campos pendientes</th></tr></thead><tbody><tr><td>Stun</td><td>SA candidata de familia Mace</td><td>Idea de aturdimiento breve; stamina, alcance, wind-up, fase activa y recuperación por definir</td><td>Enfrentamientos, interrumpibilidad, señales, precisión, daño/trauma y requisitos de aprendizaje por definir</td></tr><tr><td>Heavy Blow</td><td>SA candidata de War Hammer</td><td>Golpe comprometido; sin costes ni duraciones de fase finales</td><td>Manejo, perfil regional, movimiento y respuestas por definir</td></tr><tr><td>Crushing Arc</td><td>SA candidata de War Hammer</td><td>Arco/huella que evaluar, potencialmente con alcance físico ampliado</td><td>Número de objetivos, contactos aliados, transmisión y viabilidad de animación por definir</td></tr><tr><td>Brace</td><td>Candidata defensiva</td><td>Postura/ventana breve pagada con stamina y movimiento restringido</td><td>Solo ataques comprometidos compatibles; finta, demora, flanqueo o acción incompatible pueden superarla</td></tr></tbody></table><p>El esquema general rige todos los ejemplos; los campos ausentes no son valores por defecto. Los ejemplos ofensivos siguen la regla de cola/activación de cada modo; Brace defensivo es inmediato en ambos.</p><h2 id="defensive-actions-and-information" tabindex="-1">Acciones defensivas e información <a class="header-anchor" href="#defensive-actions-and-information" aria-label="Enlace permanente a &quot;Acciones defensivas e información&quot;">​</a></h2><p>Brace, Parry, Riposte, Counter-thrust, Dodge/Step e Interrupt son respuestas inmediatas candidatas en ambos modos, sujetas a sus propios requisitos. La entrada inmediata no elimina wind-up, recuperación ni elegibilidad.</p><p>Brace podría durar <strong>unos 2 segundos solo como ilustración de prototipo</strong>. Cuesta stamina y restringe movimiento. Un ataque comprometido compatible que llegue dentro de la ventana puede recibir reducción de daño/trauma y provocar una respuesta fuerte centrada en penetración/impulso. Si no llega ningún ataque, se desperdician stamina/tiempo/recuperación. Finta, demora, flanqueo y ataques incompatibles son opciones de contrajuego, no garantías ni fórmulas.</p><table tabindex="0"><thead><tr><th>Información</th><th>Lectura con estado Propuesto</th></tr></thead><tbody><tr><td>Todos los jugadores</td><td>Animación, postura y sonido</td></tr><tr><td>Tactics intermedio</td><td>Señal genérica como «preparando un ataque comprometido»</td></tr><tr><td>Tactics mayor</td><td>Señal de familia de acción como «cargando un golpe descendente»</td></tr></tbody></table><p>No revelar soluciones de «pulsá Brace ahora». Umbrales exactos, información, accesibilidad y señales engañosas siguen sin decidirse. Tactics mejora la información en lugar de decidir secretamente la respuesta.</p><h2 id="failure-and-balance" tabindex="-1">Fallo y equilibrio <a class="header-anchor" href="#failure-and-balance" aria-label="Enlace permanente a &quot;Fallo y equilibrio&quot;">​</a></h2><p>Preferir tiempos, alcance, orientación, stamina, recuperación, contrajuego y enfrentamientos incompatibles como causas de fallo frente a RNG arbitrario de «falló la activación de SA» después de cumplirse condiciones válidas. Esto no elimina el acierto/fallo existente ni el fizzle mágico: <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Accuracy y Consistency</a> siguen siendo conceptos separados. Familiarity debería mejorar ejecución con beneficios modestos, no enormes bonificaciones de daño bruto.</p><p>Cobro al interrumpirse, recursión de respuestas, resultados de disparo almacenados, reglas de cancelación/reemplazo, cambios de preparación y encadenamiento de acciones requieren contratos de prototipo. Aquí no se completa ningún catálogo ni pasada numérica.</p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Alcance numérico de prueba de Batch 06 <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Enlace permanente a &quot;Alcance numérico de prueba de Batch 06&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">perfil de tres armas</a> asigna valores de prueba con estado Experimental a Longsword, Spear y War Hammer. Sus reglas de fases, recursos, cadencia, Flow, Familiarity marcial y preparación solo se aplican a esa prueba futura. Los ejemplos anteriores siguen siendo alternativas históricas fuera de este perfil; de ello no se deriva equilibrio definitivo, implementación de juego ni asignación numérica de hechizos.</p>',26)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
